test('one ribbon spans and clips its independent task period',()=>{assert.deepEqual(periodSpan('2026-10-25','2026-10-28','2026-10-26'),{start:1,end:4});assert.deepEqual(periodSpan('2026-10-26','2026-11-05','2026-10-26','2026-10-28'),{start:3,end:8});assert.equal(periodSpan('2026-10-29','2026-10-27','2026-10-26'),null);assert.equal(periodSpan('2026-11-02','2026-11-04','2026-10-26'),null);});
test('shelf includes every visible project, filters explicit periods, and retains selected work',()=>{const model=structuredClone(base);model.tasks.push({id:'unplanned',project_id:'printing',start:'2026-12-01',end:'2026-12-02',period_explicit:false},{id:'reference',project_id:'printing',owned:false});model.cubes.push({id:'outside',task_id:'unplanned',project_id:'printing'},{id:'reference',task_id:'reference',project_id:'printing'},{id:'chosen',task_id:'presentation',project_id:'sculpt',selected_date:'2026-10-29'},{id:'cancelled',project_id:'printing',available:false});assert.deepEqual(availableCubes(model,'2026-10-29').map(c=>c.id),['outside','chosen']);model.projects[0].visible=false;assert.deepEqual(availableCubes(model,'2026-10-29').map(c=>c.id),['chosen']);});
test('proposal, chosen and timed placement are distinct',()=>{assert.equal(placementState(base.cubes[0],'2026-10-26'),'suggestion');assert.equal(placementState({selected_date:'2026-10-26'},'2026-10-26'),'selected');assert.equal(placementState({selected_date:'2026-10-26',start:'14:00'},'2026-10-26'),'timed');assert.equal(placementState({selected_date:'2026-10-27'},'2026-10-26'),'elsewhere');});
test('merge keeps exact sum across selected, mixed-stage and different-parent Work parts but refuses facts/external kinds',()=>{assert.deepEqual(mergeEligibility(base.cubes),{ok:true,minutes:120});for(const patch of [{selected_date:base.today,start:'17:00'},{task_id:'other'},{segment_id:'other'}])assert.equal(mergeEligibility([base.cubes[0],{...base.cubes[1],...patch}]).ok,true);for(const patch of [{actual_minutes:1},{progress_percent:1},{can_delete:false},{kind:'prep'},{task_id:null,source_task_allocations:[]}])assert.equal(mergeEligibility([base.cubes[0],{...base.cubes[1],...patch}]).ok,false);assert.equal(mergeEligibility([base.cubes[0]]).ok,false);});
test('timeline uses facts for completion and unknown state rather than calendar assumptions',()=>{assert.equal(taskTimelineState({date:'2026-10-01'},base.today).key,'unknown');assert.equal(taskTimelineState({status:'done'},base.today).key,'done');assert.equal(taskTimelineState({progress_percent:12},base.today).key,'current');assert.equal(taskTimelineState({date:'2026-11-01'},base.today).key,'future');});
test('calendar conflict combines distinct source-labelled times once',()=>{assert.equal(eventTimeLabel({start:'19:00',end:'22:00',conflict:true,alternatives:[{kind:'calendar',start:'19:00',end:'22:00'},{kind:'calendar',start:'19:00',end:'22:00'},{kind:'work',start:'18:00',end:'21:00'}]}),'Календарь 19:00–22:00 · Work 18:00–21:00');assert.equal(eventTimeLabel({all_day:true}),'Весь день');});
test('deadline provenance never promotes provisional or unknown dates',()=>{assert.equal(deadlineLabel('inferred_provisional'),'Предварительный срок');assert.equal(deadlineLabel('planning_target'),'Плановый ориентир');assert.equal(deadlineLabel('source_sheet'),'Срок по таблице');assert.ok(deadlineLabel('unknown').includes('не уточнён'));});
test('common lesson prep and reviews belong only to their source day',()=>{const model={...base,cubes:[{id:'prep',kind:'prep',planned_date:'2026-10-26',available:true},{id:'review',kind:'weekly_review',planned_date:'2026-11-01',available:true},{id:'general',kind:'task',available:true}]};assert.deepEqual(availableCubes(model,'2026-10-26').map(c=>c.id),['prep','general']);});
test('gray calendar offers belong to the source day while one Sage offer stays available on any date',()=>{const source={...base,cubes:[{id:'gray',kind:'calendar_optional',calendar_role:'optional_day',availability:'day',source_date:base.today,available:true},{id:'sage',kind:'calendar_optional',calendar_role:'evergreen',availability:'any_day',source_date:base.today,available:true}]};assert.deepEqual(availableCubes(source,base.today).map(c=>c.id),['gray','sage']);assert.deepEqual(availableCubes(source,'2027-03-14').map(c=>c.id),['sage']);assert.match(calendarOfferLabel(source.cubes[0]),/Возможное/);assert.match(calendarOfferLabel(source.cubes[1]),/Всегда актуально/);assert.equal(cubeDurationLabel({minutes:0,duration_unknown:true,requires_estimate:true}),'Длительность не указана');});
test('role-gated calendar movement never unlocks fixed, unknown or untimed red events',()=>{assert.equal(canMoveCalendarEvent({calendar_role:'flexible',movable:true}),true);for (const event of [{calendar_role:'fixed',movable:false},{calendar_role:'fixed',movable:true},{calendar_role:'unknown',movable:false},{calendar_role:'flexible',movable:false},{}]) assert.equal(canMoveCalendarEvent(event),false);const source={...base,events:[{id:'fixed',title:'Фиксированный урок',date:base.today,start:'12:00',end:'13:00',calendar_role:'fixed',movable:false},{id:'flex',title:'Переносимый блок',date:base.today,start:'14:00',end:'15:00',calendar_role:'flexible',movable:true}]};const html=calendarMarkup(source,{mode:'week',date:base.today,week_start:base.today});const fixed=html.match(/<div class="calendar-event[^"]*"[^>]+data-event-id="fixed"[^>]*>/)?.[0],flex=html.match(/<div class="calendar-event[^"]*"[^>]+data-event-id="flex"[^>]*>/)?.[0];assert.ok(fixed?.startsWith('<div'));assert.ok(!fixed.includes('draggable'));assert.ok(flex?.startsWith('<div'));assert.ok(flex.includes('draggable="true"'));assert.ok(flex.includes('data-action="open-calendar-event"'));});
test('calendar offers lead the common shelf ahead of current and future course forecasts',()=>{const rows=[{id:'future',planned_date:'2026-11-05'},{id:'current',planned_date:base.today},{id:'sage',kind:'calendar_optional',calendar_role:'evergreen'},{id:'gray',kind:'calendar_optional',calendar_role:'optional_day'}];assert.deepEqual(rows.sort((a,b)=>shelfPriority(a,base.today)-shelfPriority(b,base.today)).map(row=>row.id),['gray','sage','current','future']);});
test('compact event summary prioritizes the webinar conflict and counts every extra event',()=>{const lesson={id:'lesson',title:'Никита',date:'2026-10-29'},webinar={id:'webinar',title:'Скульпт вебинар',date:'2026-10-29',conflict:true};const events=[lesson,webinar];assert.deepEqual(eventSummary(events),{primary:webinar,count:2,additional:1,hasConflict:true});assert.deepEqual(events,[lesson,webinar]);const markup=calendarMarkup({...base,events},{mode:'month',date:base.today,week_start:base.today,window_start:base.today});assert.ok(markup.includes('data-event-summary="webinar"'));assert.ok(markup.includes('2 события'));assert.ok(markup.includes('ещё 1'));assert.ok(markup.includes('event-uncertainty'));assert.equal((markup.match(/data-testid="day-cell"/g)||[]).length,28);});
test('current project anchor follows owned planning periods without inventing progress or including history',()=>{const native={id:'current',project_id:'printing',title:'Текущая презентация',start:'2026-10-26',end:'2026-10-28',progress_percent:0,status:'available'};const source={today:base.today,tasks:[native,{...native,id:'history',end:'2026-10-25'},{...native,id:'outside',owned:false},{...native,id:'future',start:'2026-10-27'},{...native,id:'done',status:'done'},{...native,id:'other-project',project_id:'sculpt'}]};const before=structuredClone(source);assert.deepEqual(currentProjectTasks(source,'printing'),[native]);assert.deepEqual(source,before);assert.equal(native.progress_percent,0);assert.equal(native.status,'available');});
test('arrow dates retain deadline/source basis and never invent actual completion dates',()=>{assert.deepEqual(timeArrowDate({deadline:'2026-10-23',date:'2026-10-26',deadline_kind:'source_sheet',status:'active'}),{date:'2026-10-23',basis:'deadline',label:'Срок по таблице'});assert.deepEqual(timeArrowDate({date:'2026-09-11',status:'done'}),{date:'2026-09-11',basis:'source_date',label:'Дата из источника'});assert.equal(timeArrowDate({status:'waiting'}),null);});
test('arrow completion requires full_assignment true, never generic done, analysis or Work100%',()=>{const task={deadline:'2026-10-23',deadline_kind:'source_sheet',status:'active',source_status:'active',work_progress_percent:5.6};assert.equal(timeArrowStatus(task,base.today).key,'overdue');for (const kind of ['inferred_provisional','provisional','planning_target','unknown']) assert.notEqual(timeArrowStatus({...task,deadline_kind:kind},base.today).key,'overdue');const done=timeArrowStatus({...task,status:'done',full_completion:true,work_progress_percent:null},base.today);assert.equal(done.key,'done');assert.equal(done.sourceDone,true);assert.equal(done.workDone,false);assert.notEqual(timeArrowStatus({...task,status:'done',source_status:'done',full_completion:false},base.today).key,'done');assert.notEqual(timeArrowStatus({...task,status:'done',source_status:'done',work_progress_percent:100},base.today).key,'done');assert.equal(timeArrowStatus({...task,status:'waiting',source_status:'waiting',work_progress_percent:100},base.today).workDone,true);assert.equal(timeArrowStatus({...task,deadline:'2026-11-15',work_progress_percent:0},base.today).key,'upcoming');});
test('arrow keeps real date spacing, groups collisions, excludes hidden/reference scope and separates undated work',()=>{const source={today:'2026-10-26',projects:[{id:'print',visible:true,start:'2026-10-01',end:'2026-12-01',tasks:[{id:'one',date:'2026-10-10'},{id:'two',date:'2026-10-11'},{id:'same-day',date:'2026-10-11'},{id:'later',date:'2026-11-10'},{id:'reference',date:'2027-03-01',owned:false},{id:'undated'}]},{id:'hidden',visible:false,tasks:[{id:'hidden-task',date:'2026-01-01'}]}]};const before=structuredClone(source),axis=projectArrowModel(source);assert.deepEqual(source,before);assert.equal(axis.start,'2026-10-01');assert.equal(axis.end,'2026-12-01');assert.deepEqual(axis.groups.map(group=>group.date),['2026-10-10','2026-10-11','2026-11-10']);assert.equal(axis.groups[1].items.length,2);assert.equal(axis.groups[1].y-axis.groups[0].y,axis.pixelsPerDay);assert.equal(axis.groups[2].y-axis.groups[1].y,30*axis.pixelsPerDay);const boxes=placeArrowLabelBoxes(axis.groups.map((group,id)=>({id,y:group.y,height:40})),axis.height,axis.todayY);for(let i=1;i<boxes.length;i++)assert.ok(boxes[i].top-(boxes[i-1].top+boxes[i-1].height)>=8-1e-7);assert.deepEqual(axis.undated.map(row=>row.task.id),['undated']);assert.ok(axis.ticks.some(tick=>tick.date==='2026-10-26'));});
test('arrow label line boxes stay separated at a Tuesday endpoint and around Today near a Monday tick',()=>{
  for (const today of ['2026-10-26','2026-10-27']) for (const start of ['2026-09-11','2026-10-13']) {
    const axis=projectArrowModel({today,projects:[{id:'course',visible:true,start,end:'2026-12-22',tasks:[{id:'final',date:'2026-12-22',deadline:'2026-12-22',deadline_kind:'source_brief'}]}]});
    const before=structuredClone(axis),labels=axisDateLabels(axis.ticks,axis.todayY),boxes=[...labels.map(tick=>({center:tick.y,height:15.4})),{center:axis.todayY,height:18}].sort((a,b)=>a.center-b.center);
    assert.deepEqual(axis,before);assert.ok(labels.some(tick=>tick.date==='2026-12-21'));assert.ok(!labels.some(tick=>tick.date==='2026-12-22'));assert.equal(axis.groups[0].date,'2026-12-22');assert.equal(axis.groups[0].y,axis.endY);
    for(let index=1;index<boxes.length;index++) assert.ok(boxes[index].center-boxes[index].height/2-(boxes[index-1].center+boxes[index-1].height/2)>=3.99);
    if(today==='2026-10-27') assert.ok(!labels.some(tick=>tick.date==='2026-10-26'));
  }
});
