test('synthetic package windows create distinct true-dated start and deadline entries without forecast/component phantoms',()=>{
  const source=syntheticPackageFixture(),before=structuredClone(source),axis=projectArrowModel(source),rows=axis.groups.flatMap(group=>group.items),package2=rows.filter(row=>row.task.id==='package2');assert.deepEqual(source,before);assert.deepEqual(package2.map(row=>[row.eventKind,row.date]),[['start','2026-11-09'],['deadline','2026-11-15']]);assert.equal(rows.length,6);assert.ok(!rows.some(row=>['screen','slides','setup','first'].includes(row.task.id)));assert.deepEqual(axis.undated.map(row=>row.task.id),['first']);const period=axis.periods.find(item=>item.task.id==='package2');assert.ok(Math.abs(period.height-6*axis.pixelsPerDay)<1e-8);for(let index=0;index<axis.groups.length;index++)for(let other=0;other<index;other++)assert.ok(Math.abs(axis.groups[index].y-axis.groups[other].y)>=20 || Math.abs(axis.groups[index].nodeX-axis.groups[other].nodeX)>=20);
});
test('cursor-anchored arrow zoom and month boundaries preserve true calendar coordinates through leap/year transitions',()=>{
  const scroll=300,cursor=200,oldScale=12,nextScale=24,nextScroll=arrowZoomAnchor(scroll,cursor,oldScale,nextScale);assert.equal((scroll+cursor-24)/oldScale,(nextScroll+cursor-24)/nextScale);const bands=arrowMonthBands('2028-02-27','2028-03-03',8);assert.deepEqual(bands.map(band=>[band.start,band.end,band.height]),[['2028-02-27','2028-03-01',24],['2028-03-01','2028-03-04',24]]);const source=syntheticPackageFixture(),small=projectArrowModel(source,{pixelsPerDay:4}),large=projectArrowModel(source,{pixelsPerDay:32});assert.deepEqual(small.groups.flatMap(group=>group.items.map(row=>row.entryId)),large.groups.flatMap(group=>group.items.map(row=>row.entryId)));assert.ok(large.ticks.length>small.ticks.length);assert.equal((large.groups[1].y-24)/(small.groups[1].y-24),8);
});
test('measured-height label packing maintains at least8px gaps at every scale while retaining every date point',()=>{
  const days=[0,5,6,7,17,19,30,32,42,59,65,66,72,73,79,80,86,87,93,94,100,102];
  for(let scale=4;scale<=48;scale++){const items=days.map((day,id)=>({id,y:24+day*scale,height:(scale<=6 ? 30 : 40)+(id%5===0 ? 15 : 0),priority:2000-Math.abs(day-45)})),before=structuredClone(items),height=102*scale+50,todayY=24+45*scale,placed=placeArrowLabelBoxes(items,height,todayY,{gap:9}),boxes=[...placed,{top:todayY-10,height:20}].sort((a,b)=>a.top-b.top);assert.deepEqual(items,before);assert.ok(placed.length>=2);for(const box of placed){assert.ok(box.top>=8-1e-7);assert.ok(box.top+box.height<=height-8+1e-7);}for(let i=1;i<boxes.length;i++)assert.ok(boxes[i].top-(boxes[i-1].top+boxes[i-1].height)>=8-1e-7);}
  const bounds=arrowZoomBounds(102,680);assert.equal(bounds.min*102+120,680);assert.equal(bounds.max,48);
});
test('floating inspector avoids the original double-click target and stays bounded on desktop and phone',()=>{
  for(const [width,height,rect] of [[1440,900,{left:28,right:240,top:200,bottom:230}],[1440,900,{left:750,right:940,top:650,bottom:680}],[390,900,{left:12,right:180,top:200,bottom:230}],[390,900,{left:210,right:370,top:700,bottom:730}],[390,900,{left:12,right:180,top:430,bottom:455}]]){const box=inspectorBox(rect,width,height);assert.ok(box.left>=12);assert.ok(box.left+box.width<=width-12+1e-7);assert.ok(box.top>=12);assert.ok(box.top+box.maxHeight<=height-12+1e-7);assert.ok(box.left+box.width<=rect.left || box.left>=rect.right || box.top+box.maxHeight<=rect.top || box.top>=rect.bottom);}
});
