test('month uses four explicit period summaries without clipped ribbons and reveals every full weekly task title',()=>{const source=structuredClone(base);source.tasks.push({...source.tasks[0],id:'second',title:'Вторая длинная задача, которая должна оставаться целиком читаемой при раскрытии недели'});const context={mode:'month',date:base.today,week_start:base.today,window_start:base.today,expanded_week:null};const compact=calendarMarkup(source,context);assert.equal((compact.match(/data-testid="month-period-summary"/g)||[]).length,4);assert.equal((compact.match(/data-action="show-periods"/g)||[]).length,4);assert.ok(compact.includes('data-period-count="2"'));assert.ok(!compact.includes('data-testid="task-ribbon"'));assert.ok(!compact.includes('data-testid="week-period-details"'));const expanded=calendarMarkup(source,{...context,expanded_week:base.today});assert.ok(expanded.includes('data-testid="week-period-details"'));assert.ok(expanded.includes('Создать презентацию &lt;Blender&gt;'));assert.ok(expanded.includes(source.tasks[1].title));assert.ok(expanded.includes('Скрыть список'));assert.deepEqual(periodTasksForWeek(source,base.today).map(item=>item.task.id),['presentation','second']);});
