async function withClientTransport(transport, exercise, {rawContext=false}={}) {
  const original = {document:globalThis.document,window:globalThis.window,fetch:globalThis.fetch,setInterval:globalThis.setInterval};
  const nodes = new Map(['planner','notice','sync-status'].map(id=>[id,{dataset:{},listeners:{},classList:{toggle(){}},setAttribute(){},addEventListener(name,callback){this.listeners[name]=callback;},querySelectorAll(){return [];},innerHTML:'',textContent:'',hidden:true}]));
  globalThis.document = {activeElement:null,getElementById:id=>nodes.get(id),addEventListener(){}};
  globalThis.window = {addEventListener(){}};
  globalThis.setInterval = ()=>0;
  configurePeriodTransport({async api(path,method,body){
    const legacyPath=path.replace('/api/work/period/','/api/');
    const legacyBody=legacyPath==='/api/context' && !rawContext ? body.patch : body;
    const response=await transport(legacyPath,{method,body:JSON.stringify(legacyBody)});
    const value=await response.json();
    if(!response.ok)throw Object.assign(new Error(value.error || 'Failed'),{status:response.status});
    return value;
  }});
  try {
    const client = await import(`../work-period/app.js?client-race=${Math.random()}`);
    await new Promise(resolve=>setImmediate(resolve));
    await exercise(client,nodes);
  } finally {
    for (const [key,value] of Object.entries(original)) {if (value === undefined) delete globalThis[key];else globalThis[key]=value;}
  }
}
function aliasTransport(state,calls){return async(url,options)=>{if(url==='/api/model')return {ok:true,json:async()=>structuredClone(state)};const body=JSON.parse(options.body);if(url==='/api/context'){state.context={...state.context,...body};state.revision++;return {ok:true,json:async()=>({context:state.context,revision:state.revision})};}calls.push(body);if(body.expected_revision!==state.revision)return {ok:false,status:409,json:async()=>({error:'Conflict'})};const key=body.action==='cube_rename' ? 'cube_id' : body.action==='calendar_event_rename' ? 'event_id' : 'task_id',id=body.data[key],rows=body.action==='cube_rename' ? state.cubes : body.action==='calendar_event_rename' ? state.events : body.action==='task_rename' ? state.tasks : state.projects.flatMap(project=>[...(project.tasks || []),...(project.tasks || []).flatMap(task=>task.components || [])]);for(const object of rows.filter(row=>row.id===id)){object.source_title=object.source_title || object.title;object.title=body.data.title;}state.revision++;return {ok:true,json:async()=>structuredClone(state)};};}
