function gestureFixture(cube,edge=null){
  const start=cube.start.split(':').map(Number).reduce((sum,n,index)=>sum+n*(index===0 ? 60 : 1),0),top=(start-660)*2;
  const canvas={dataset:{date:cube.selected_date,startMinute:'660',endMinute:'1200',pixelsPerMinute:'2'},getBoundingClientRect:()=>({top:0,bottom:1080,left:0,right:300}),closest:()=>null};
  const block={dataset:{timelineId:cube.id,timelineKind:'cube',startMinute:String(start),durationMinutes:String(cube.minutes),editableDrag:'true'},style:{},classList:{add(){},remove(){}},getBoundingClientRect:()=>({top,bottom:top+cube.minutes*2,left:48,right:300}),closest:()=>canvas,querySelector:()=>({textContent:''}),setPointerCapture(){},releasePointerCapture(){}};
  const handle=edge ? {dataset:{timelineResize:edge,cubeId:cube.id},focus(){}} : null;
  const target={closest:selector=>selector==='[data-timeline-id]' ? block : selector==='[data-timeline-resize]' ? handle : null};
  return {block,canvas,event:{target,button:0,pointerId:1,clientX:100,clientY:edge==='end' ? top+cube.minutes*2 : top+(edge ? 0 : 10),preventDefault(){}}};
}
