test('immediate cube-editor or day context followed by work edit waits for local context revision',async()=>{
  for (const patch of [{cube_id:'a'},{date:'2026-10-27',week_start:'2026-10-26'}]) {
    const calls=[];let releaseContext;let serverRevision=1;const state={...structuredClone(base),context:{mode:'week',date:base.today,week_start:base.today}};
    await withClientTransport(async(url,options)=>{
      if (url==='/api/model') return {ok:true,json:async()=>({...state,revision:serverRevision})};
      const body=JSON.parse(options.body);calls.push({url,body});
      if (url==='/api/context') {await new Promise(resolve=>{releaseContext=resolve;});state.context={...state.context,...body};return {ok:true,json:async()=>({context:state.context,revision:++serverRevision})};}
      assert.equal(body.expected_revision,serverRevision);return {ok:true,json:async()=>({...state,revision:++serverRevision})};
    },async(client)=>{
      const contextWrite=client.updateContext(patch);
      const edit=client.command('cube_select',{cube_id:'a',date:'2026-10-27'});
      await new Promise(resolve=>setImmediate(resolve));
      assert.deepEqual(calls.map(call=>call.url),['/api/context']);
      releaseContext();await Promise.all([contextWrite,edit]);
      assert.equal(calls[1].url,'/api/command');assert.equal(calls[1].body.expected_revision,2);
    });
  }
});
test('an external edit after the local context write still returns409 and is never blindly retried',async()=>{
  let serverRevision=1,commands=0;const state={...structuredClone(base),context:{mode:'week',date:base.today,week_start:base.today}};
  await withClientTransport(async(url,options)=>{
    if (url==='/api/model') return {ok:true,json:async()=>({...state,revision:serverRevision})};
    if (url==='/api/context') {state.context={...state.context,...JSON.parse(options.body)};serverRevision=2;return {ok:true,json:async()=>({context:state.context,revision:2})};}
    commands++;assert.equal(JSON.parse(options.body).expected_revision,2);serverRevision=3;return {ok:false,status:409,json:async()=>({error:'Conflict'})};
  },async(client,nodes)=>{
    await client.updateContext({cube_id:'a'});
    assert.equal(await client.command('cube_select',{cube_id:'a',date:base.today}),null);
    assert.equal(commands,1);assert.match(nodes.get('notice').textContent,/другом окне или агентом/);
    assert.equal(client.plannerState().model.revision,3);
  });
});
test('a context revision jump rereads the external plan and blocks the already pending intent',async()=>{
  let serverRevision=1,commands=0,reads=0;const state={...structuredClone(base),context:{mode:'week',date:base.today,week_start:base.today}};
  await withClientTransport(async(url,options)=>{
    if (url==='/api/model') {reads++;return {ok:true,json:async()=>({...structuredClone(state),revision:serverRevision})};}
    if (url==='/api/context') {state.context={...state.context,...JSON.parse(options.body)};state.tasks[0].title='Задача изменена агентом';serverRevision=4;return {ok:true,json:async()=>({context:state.context,revision:4})};}
    commands++;assert.equal(JSON.parse(options.body).expected_revision,4);return {ok:true,json:async()=>({...state,revision:++serverRevision})};
  },async(client,nodes)=>{
    const contextWrite=client.updateContext({cube_id:'a'});
    const pendingEdit=client.command('cube_select',{cube_id:'a',date:base.today});
    await contextWrite;assert.equal(await pendingEdit,null);assert.equal(commands,0);assert.equal(reads,2);
    assert.equal(client.plannerState().model.tasks[0].title,'Задача изменена агентом');assert.match(nodes.get('notice').textContent,/проверьте данные/);
    assert.ok(await client.command('cube_select',{cube_id:'a',date:base.today}));assert.equal(commands,1);
  });
});


test('production context queue sends strict CAS envelopes with separate stable operation IDs',async()=>{
  const state=structuredClone(base),calls=[];
  await withClientTransport(async(url,options)=>{
    if(url==='/api/model')return {ok:true,json:async()=>structuredClone(state)};
    const body=JSON.parse(options.body);calls.push(body);
    assert.deepEqual(Object.keys(body).sort(),['expected_revision','patch','request_id']);
    assert.equal(body.expected_revision,state.revision);assert.match(body.request_id,/^[0-9a-f-]{36}$/);
    state.context={...state.context,...body.patch};state.revision++;
    return {ok:true,json:async()=>({context:state.context,revision:state.revision})};
  },async(client)=>{
    await Promise.all([client.updateContext({mode:'month'}),client.updateContext({date:'2026-10-27'})]);
    assert.equal(calls.length,2);assert.deepEqual(calls.map(call=>call.expected_revision),[1,2]);assert.notEqual(calls[0].request_id,calls[1].request_id);
    assert.equal(client.plannerState().contextValue.mode,'month');assert.equal(client.plannerState().contextValue.date,'2026-10-27');
  },{rawContext:true});
});

test('production context CAS409 rereads external state and skips already queued stale patches',async()=>{
  const state=structuredClone(base),calls=[];let reads=0;
  await withClientTransport(async(url,options)=>{
    if(url==='/api/model'){reads++;return {ok:true,json:async()=>structuredClone(state)};}
    const body=JSON.parse(options.body);calls.push(body);state.revision=4;state.context={mode:'week',date:'2026-10-28'};
    return {ok:false,status:409,json:async()=>({error:'Conflict'})};
  },async(client,nodes)=>{
    await Promise.all([client.updateContext({mode:'month'}),client.updateContext({date:'2026-10-27'})]);
    assert.equal(calls.length,1);assert.equal(reads,2);assert.equal(state.revision,4);
    assert.equal(client.plannerState().contextValue.date,'2026-10-28');assert.equal(client.plannerState().contextValue.mode,'week');assert.match(nodes.get('notice').textContent,/другом окне/);
  },{rawContext:true});
});

test('context selection during an in-flight work edit waits for its own new revision',async()=>{
  const state=structuredClone(base),calls=[];let release;
  await withClientTransport(async(url,options)=>{
    if(url==='/api/model')return {ok:true,json:async()=>structuredClone(state)};
    const body=JSON.parse(options.body);calls.push({url,body});assert.equal(body.expected_revision,state.revision);
    if(url==='/api/command'){await new Promise(resolve=>{release=resolve;});state.revision++;return {ok:true,json:async()=>structuredClone(state)};}
    state.context={...state.context,...body.patch};state.revision++;return {ok:true,json:async()=>({context:state.context,revision:state.revision})};
  },async(client)=>{
    const edit=client.command('period_set',{task_id:'presentation',start:'2026-10-26',end:'2026-10-28'});await new Promise(resolve=>setImmediate(resolve));
    const selection=client.updateContext({mode:'month'});await new Promise(resolve=>setImmediate(resolve));assert.deepEqual(calls.map(call=>call.url),['/api/command']);
    release();await Promise.all([edit,selection]);assert.deepEqual(calls.map(call=>call.body.expected_revision),[1,2]);assert.equal(client.plannerState().contextValue.mode,'month');
  },{rawContext:true});
});
